from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[2];A=ROOT/'analysis/county-methodology/a-g'
def main():
 ledger=json.loads((A/'ledger.json').read_text());by={r['county']:r for r in ledger['counties']}
 collin=json.loads((A/'collin-daily.json').read_text());raw=json.loads((A/'collin-native-20261026.json').read_text());control=json.loads((A/'collin-control.json').read_text());text=(A/'collin-site-20261026.txt').read_text();sites=[int(s.replace(',',''))for s in re.findall(r'^EV\d{3},.*?\s+([\d,]+)\s*$',text,re.M)];assert len(sites)==42 and sum(sites)==30065;latest=collin[-1];assert latest['date']=='2026-10-26'and sum(latest['counts'].values())==29725 and len(latest['counts'])==266 and latest['unavailable_precincts']==['52'];assert '29932 ordinary source rows; 133 provisional rows excluded' in latest['note'];assert 29932+133==sum(sites)
