 assert len(by)==94 and set(by)==set(json.loads((A.parent/'a_g-counties.json').read_text()))
 ledger['dispositions']=dict(Counter(r['disposition']for r in ledger['counties']));ledger['verification']={'all94_individually_screened':True,'source_urls_and_hashes_validated':True,'synthetic_collector_contracts':15,'official_grayson_contracts':6,'collin_site_count':42,'collin_allcheckin_control':30065,'collin_native_replay_matches_independent_probe':all(s['counts']==d['counts']for s,d in zip(collin,raw['days']))};assert ledger['verification']['collin_native_replay_matches_independent_probe'];(A/'ledger.json').write_text(json.dumps(ledger,indent=2)+'\n')
 lines=['# A–G county precinct methodology review','',f"Frozen snapshot: `{ledger['generated_at']}`. All 94 assigned counties were individually checked against eight daily paired-coverage results, both native precinct universes, every retained source date/hash/unknown label and independent completed controls. No source gaps, zero votes or geographic aliases were invented.",'','## Accepted candidates','','- **Collin:** the state Oct26file has13 votes. The official dated county workbook exposes29,932 ordinary Regular rows and133 Provisional rows, exactly reconciling the42-site inclusive check-in total 30,065. The collector excludes provisional rows and withholds the entire native 52 cell because one identity is blank. It retains29,725 ordinary votes in266 positive native precincts. All eight dated outputs are available; omitted precincts remain unknown.','- **Grayson:** official certified native presidential returns cover all 41 historical precincts, versus 13 previously classified. All 13 previous values agree. Both candidate totals (Trump 50,556, Harris 14,800), all other candidates and all 24 candidate/method totals conserve to the independently published official county summary. This restores classification without changing turnout or geography.','','## Rejected source hypotheses','','- **Gregg:** county pages and native 21 map confirm the native 1–21 district universe but do not define how each detailed SOS subdivision belongs to it. Some current labels are foreign or malformed, making generic numeric truncation unsafe. No turnout added.','- **Guadalupe:** the official May 13, 2025 order verifies 208 → 208 + 233 and 415 → 415 + 402, but supplies no 2024 four-digit subdivision-to-native relationship. Numerictruncation remains rejected.','- **Anderson, Bexar, Galveston and Grimes:** checked 07:51 and 16:30 editions do not reveal an earlier completed Oct 26 precinct source. Bexar current 18,364 is below the independent 43,839 control. Galveston moves 1 → 3 votes. These are underfilled publication observations, not completed same-day estimates.','','## Verification','','`python -m unittest discover -s sources/county-methodology/a-g -p "test_method_a_g*.py"` passes 21 contracts. Initial missing-collector and missing-native-reference verification were exercised red; CLI stdout contract was also red before implementation. Two live Collin collector runs pass, and their counts agree exactly with the independent earlier memory-only workbook probe. Every official Grayson candidate/method column and exact 41-ID partition reconciles; source PDF SHA256 editions are pinned. No raw voter bytes or identities were saved.','','The full machine-readable ledger is `analysis/county-methodology/a-g/ledger.json`; it records every county’s diagnosis, all retained source URLs/hashes, individual date coverage, missing presidential reference IDs, disposition and concrete next action. `screen.py` regenerates the initial screening; `finalize.py` attaches the reviewed evidence and validates the 94-ID partition.','','## Individual county screen','','| County | Day1 paired | Day8 paired | Missing native presidential IDs | Disposition |','|---|---:|---:|---:|---|']
 for r in ledger['counties']:
  c=r['coverage_by_day'];d1=f"{c[0].get('available_precincts',0)}/{c[0]['total_precincts']}"if c else'not admitted';d8=f"{c[-1].get('available_precincts',0)}/{c[-1]['total_precincts']}"if c else'not admitted';lines.append(f"|{r['name']}|{d1}|{d8}|{len(r['presidential_native_missing'])}|{r['disposition']}|")
 (P/'review.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'reviewed':94,'dispositions':ledger['dispositions'],'verification':ledger['verification']}))
